#include <iostream>
#include <vector>
#include <cassert>

using namespace std;

typedef long long ll;

const int MOD = 1000000007;

using matrix = vector<vector<int>>;

vector<matrix> dp;
matrix tmp;
matrix base;

matrix shift(const matrix &a, int shift)
{
    int size = (int)a.size() - 1;
    shift = (size - shift) % size;
    matrix res = a;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            res[i][j] = a[(i + shift) % size][(j + shift) % size];
        }
    }
    for (int j = 0; j < size; ++j) {
        res[size][j] = a[size][(j + shift) % size];
    }
    return res;
}

matrix operator*(const matrix &a, const matrix &b)
{
    int n = (int)a.size(), k = (int)a[0].size(), m = (int)b[0].size();
    vector<vector<int>> aa(n, vector<int>(k));
    vector<vector<int>> bb(k, vector<int>(m));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < k; ++j)
            aa[i][j] = a[i][j];
    for (int i = 0; i < k; ++i)
        for (int j = 0; j < m; ++j)
            bb[i][j] = b[i][j];
    matrix res(n, vector<int>(m, 0));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            for (int l = 0; l < k; ++l)
                res[i][j] = (res[i][j] + (long long)aa[i][l] * bb[l][j]) % MOD;
    return res;
}

int main()
{
    ll n;
    int k;
    cin >> n >> k;
    int max_depth = 0;
    {
        ll tmp = n;
        while (tmp != 0) {
            ++max_depth;
            tmp /= k;
        }
    }
    dp.resize(max_depth);
    {
        dp[0].assign(k + 1, vector<int>(k + 1, 0));
        for (int i = 0; i <= k; ++i)
            for (int j = 0; j <= k; ++j)
                dp[0][i][j] = (i == j || j == 0);
        matrix identity(k + 1, vector<int>(k + 1, 0));
        for (int i = 0; i <= k; ++i)
            identity[i][i] = 1;
        for (int depth = 1; depth < max_depth; ++depth) {
            dp[depth] = identity;
            matrix prev = dp[depth - 1];
            int curx = k;
            for (int i = 0; (1 << i) <= curx; ++i) {
                if (curx & (1 << i)) {
                    dp[depth] = prev * shift(dp[depth], (1 << i));
                    curx ^= (1 << i);
                }
                prev = prev * shift(prev, (1 << i));
            }
        }
    }
    base.assign(1, vector<int>(k + 1, 0));
    base[0][k] = 1;
    int shift_counter = 0;
    ll x = n;
    vector<int> digits;
    while (x != 0) {
        digits.push_back(x % k);
        x /= k;
    }
    int length = (int)digits.size();
    for (int idx = length - 1; idx >= 0; --idx) {
        int rest = digits[idx];
        for (int it = 0; it < rest; ++it, shift_counter = (shift_counter + 1) % k) {
            base = base * shift(dp[idx], shift_counter);
        }
    }
    int result = 0;
    for (int i = 0; i <= k; ++i) {
        result = (result + base[0][i]) % MOD;
    }
    cout << result << '\n';
    return 0;
}
